delhaize.be.apply:
try {
  const DELAY = 300;
  const SUBMIT = `input[name=promo-code] + button`;
  const COUPON = `input[name=promo-code]`

  const EVENTS = 
  [new Event('input', { bubbles: true }), 
  new Event('change'), 
  new Event('blur'), 
  new Event('focus')];
  
  EVENTS.forEach(EVENT => { 
    document.querySelector(COUPON).dispatchEvent(EVENT); 
  });
  
  setTimeout(() => {
    document.querySelector(SUBMIT).click();
  },DELAY)
}catch(e){}

